import sys
import click
from click import formatting
from click.globals import pop_context
from click.testing import CliRunner
assert click.__version__ == \"8.1.8\"
print(json.dumps({\"version\": click.__version__, \"source\": click.__file__}))
old_width = formatting.FORCED_WIDTH
old_streams = (sys.stdin, sys.stdout, sys.stderr)
try:
    with CliRunner(charset=\"nonexistent-click-encoding\").isolation(input=b\"\"):
        pass
except LookupError as error:
    width_result = {\"probe\": \"isolation_setup_failure\", \"exception\": type(error).__name__, \"width_before\": old_width, \"width_after\": formatting.FORCED_WIDTH, \"streams_restored\": all(a is b for a, b in zip(old_streams, (sys.stdin, sys.stdout, sys.stderr)))}
finally:
    formatting.FORCED_WIDTH = old_width
    sys.stdin, sys.stdout, sys.stderr = old_streams
print(json.dumps(width_result))
ctx = click.Context(click.Command(\"cleanup-probe\"))
def fail_cleanup():
    raise RuntimeError(\"cleanup failed\")
ctx.call_on_close(fail_cleanup)
try:
    with ctx:
        pass
except RuntimeError as error:
    context_result = {\"probe\": \"context_cleanup_failure\", \"exception\": type(error).__name__, \"current_context_leaked\": click.get_current_context(silent=True) is ctx}
finally:
    if click.get_current_context(silent=True) is ctx:
        pop_context()
print(json.dumps(context_result))
@click.command()
def return_one():
    return 1
@click.command()
@click.pass_context
def exit_one(ctx):
    ctx.exit(1)
runner = CliRunner()
results = []
for command in (return_one, exit_one):
    for standalone in (True, False):
        result = runner.invoke(command, standalone_mode=standalone)
        results.append({\"command\": command.name, \"standalone\": standalone, \"exit_code\": result.exit_code, \"return_value\": result.return_value, \"exception\": type(result.exception).__name__ if result.exception else None})
print(json.dumps({\"probe\": \"return_and_exit_contracts\", \"results\": results}))
snap = (sys.stdin, sys.stdout, sys.stderr, formatting.FORCED_WIDTH)
with runner.isolation():
    try:
        with runner.isolation():
            raise ValueError(\"nested body failure\")
    except ValueError:
        pass
print(json.dumps({\"probe\": \"nested_body_failure\", \"state_restored\": all(a is b for a, b in zip(snap, (sys.stdin, sys.stdout, sys.stderr, formatting.FORCED_WIDTH)))}))
